// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor as a non-zero address to be meaningful, allow wide amt
        vm.assume(depositor != address(0));
        // fund the depositor so they can send amt (if amt is huge, cap to a large but fundable bound)
        uint256 cap = type(uint160).max; // very large cap, but vm.deal takes uint256
        uint256 sendAmt = amt;
        // bound sendAmt to a feasible value for vm.deal while keeping wide range
        if (sendAmt > 1 ether * 1_000_000) {
            sendAmt = sendAmt % (1 ether * 1_000_000);
        }
        // ensure sendAmt may be zero as well; that's admissible
        vm.deal(depositor, sendAmt);

        // record previous balance as seen in contract getter
        uint256 before = c.balances(depositor);

        // perform the deposit from depositor sending sendAmt wei
        vm.prank(depositor);
        // use low-level try/catch to capture any unexpected revert but Deposit should not revert in normal path
        bool ok;
        try c.Deposit{value: sendAmt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: after calling Deposit (whether it reverted or not),
        // in the correct contract the stored balance is never less than before (monotonic non-decrease for that depositor)
        // For a revert, Deposit would not have completed state change, so balance remains >= before as well.
        uint256 after = c.balances(depositor);
        assertTrue(after >= before);
    }
}

