pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a non-zero address to be realistic
        vm.assume(depositor != address(0));
        // allow any amount including very large values; ensure depositor has funds
        uint256 fund = amount;
        // if amount is zero, still valid; vm.deal accepts zero
        vm.deal(depositor, fund);

        // read balance before
        uint256 beforeBal = c.balances(depositor);

        // perform Deposit from depositor with given amount
        vm.prank(depositor);
        // send value may be zero up to fund
        // If fund < amount, sending will revert by EVM due to insufficient balance, avoid that
        // Bound sending value by fund to ensure the EOA has that Ether
        uint256 sendVal = amount;
        if (sendVal > fund) {
            sendVal = fund;
        }
        // call Deposit with value sendVal
        bool ok;
        try c.Deposit{value: sendVal}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, reference contract guarantees balance did not decrease; mutant can wrap and decrease.
        uint256 afterBal = c.balances(depositor);

        // Single assertion: for the correct contract, if the Deposit call returned (ok==true) then afterBal >= beforeBal
        // This reads only public getter balances and the try/catch result
        // Note: If the call reverted (ok==false), we cannot assume change, so require ok implies non-decrease
        assertTrue(!ok || afterBal >= beforeBal);
    }
}

