pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor and amount, plus a second account to observe
    function testFuzz_property(address depositor, address observer, uint256 amt) public {
        // Keep addresses non-zero and wide domain; allow depositor and observer to be distinct
        vm.assume(depositor != address(0));
        vm.assume(observer != address(0));
        // allow same or different; we specifically want a case where observer != depositor
        vm.assume(depositor != observer);

        // Bound amount reasonably but allow very large values to permit overflow triggering
        amt = bound(amt, 0, type(uint256).max);

        // Fund depositor so they can send amt (cap at some high value but include very large amounts)
        vm.deal(depositor, amt);

        // Record observer's balance in contract before deposit
        uint256 before = c.balances(observer);

        // Make depositor call Deposit with value amt
        vm.prank(depositor);
        // call payable Deposit
        try c.Deposit{value: amt}() {
            // successful
        } catch {
            // ignore reverts; reference never reverts here because it reverts on overflow,
            // but we only care about observable mapping value for observer after call
        }

        uint256 after = c.balances(observer);

        // General rule: A deposit by some depositor must NOT change the stored balance of a different observer account.
        // The correct contract preserves other accounts' balances for all inputs; the mutant's overflow removal can
        // cause storage corruption/wrap that changes unrelated mapping slots for some inputs.
        assertTrue(after == before);
    }
}

