pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor and amount. General rule: after Deposit by depositor of amount > 0,
    // balances[depositor] increases by amount and balances of a different key (here address(0)) remains unchanged.
    // We express this by recording balances for depositor and address(0) before and after Deposit, and
    // assert that address(0) balance did not change (this holds for reference, and mutant that decrements
    // address(0) will make this fail for some inputs where amount>0).
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor as a non-zero address to be realistic, but allow zero too — broad domain
        vm.assume(depositor != address(this)); // avoid test contract as depositor to keep variety

        // bound amount to sensible range so vm.deal works and to avoid overflows in test bookkeeping
        amt = bound(amt, 0, 1 ether);

        // record pre-state
        uint256 beforeDepositor = c.balances(depositor);
        uint256 beforeZero = c.balances(address(0));

        // fund depositor and perform deposit as that actor
        vm.deal(depositor, amt);
        vm.prank(depositor);
        // perform Deposit payable call; catch reverts just in case
        bool ok;
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // record post-state
        uint256 afterDepositor = c.balances(depositor);
        uint256 afterZero = c.balances(address(0));

        // Single assertion expressing the invariant: if the Deposit call succeeded, depositor's balance
        // increased by amt and the balance at address(0) did not change. If Deposit reverted (ok==false), the
        // reference contract still enforces that address(0) unchanged and balances unchanged; we assert on post vs pre.
        // We combine into one boolean observed from c's public getters.
        bool prop;
        if (!ok) {
            // deposit reverted: no state change expected
            prop = (afterDepositor == beforeDepositor) && (afterZero == beforeZero);
        } else {
            // deposit succeeded: depositor increased by amt and address(0) unchanged
            prop = (afterDepositor == beforeDepositor + amt) && (afterZero == beforeZero);
        }

        assertTrue(prop);
    }
}

