pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the depositor address and an amount. We keep amounts wide but non-negative and
    // ensure the depositor has ETH to send. We observe the sum of balances for depositor and address(0)
    // before and after Deposit and assert that the increase equals the sent amount. The mutant which
    // decrements balances[address(0)] will violate this for some inputs.
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor non-zero to be a meaningful actor
        if (depositor == address(0)) depositor = address(1);

        // bound the amount to a reasonable range but keep it wide
        amt = bound(amt, 0, 1 ether);

        // fund the depositor so the call can send ETH
        vm.deal(depositor, amt);

        // read balances for depositor and address(0) before
        uint256 before_dep = c.balances(depositor);
        uint256 before_zero = c.balances(address(0));

        // perform deposit as depositor
        vm.prank(depositor);
        c.Deposit{value: amt}();

        // read balances after
        uint256 after_dep = c.balances(depositor);
        uint256 after_zero = c.balances(address(0));

        // compute total stored-sum before and after (we only can read these two keys via public getter)
        uint256 before_sum = before_dep + before_zero;
        uint256 after_sum = after_dep + after_zero;

        // The reference contract guarantees that the total stored-sum increases exactly by amt.
        // The mutant that subtracts from balances[address(0)] will cause after_sum < before_sum + amt for some inputs.
        assertTrue(after_sum == before_sum + amt);
    }
}

