// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - uint256 amt: amount sent with Deposit
    // - address eoa: the externally owned account that will send the transaction (tx.origin)
    // - address other: some other address to check balances differ (can be same as eoa)
    function testFuzz_property(uint256 amt, address eoa, address other) public {
        // keep amounts reasonable and non-zero to exercise state change
        amt = bound(amt, 1, 1 ether);
        // avoid zero addresses for clarity
        vm.assume(eoa != address(0));
        vm.assume(other != address(0));

        // Deploy a simple forwarder contract that will call c.Deposit() on behalf of eoa.
        // This models a contract caller so that tx.origin != msg.sender in c.
        Forwarder f = new Forwarder(address(c));

        // Fund the EOA so it can send ETH to forwarder and then forwarder calls c
        vm.deal(eoa, amt);

        // EOA sends ETH to the forwarder and triggers it to call c.Deposit() from the forwarder's context.
        vm.prank(eoa);
        // call Forwarder.doForward and send amt; forwarder will call c.Deposit() (so in c: msg.sender==forwarder, tx.origin==eoa)
        f.doForward{value: amt}();

        // After the call, in the correct contract balances[msg.sender] was increased where msg.sender is the forwarder.
        // The mutant would instead increase balances[tx.origin] (the EOA). We assert a universal property about the reference:
        // For all inputs, balances[forwarder] >= balances[other] if forwarder == other or when other is arbitrary we at least
        // assert that balances[forwarder] equals the recorded deposit amount (i.e., amt). This reads the public getter.

        // The reference guarantees that balances[forwarder] == amt
        address forwarderAddr = address(f);
        // read the balances via public getter
        uint256 balForwarder = c.balances(forwarderAddr);

        // Single assertion: reference contract always attributes the deposit amount to msg.sender (the forwarder), so balForwarder == amt.
        // The mutant (which uses tx.origin) will leave balForwarder == 0 for cases when tx.origin != msg.sender, thus this assertion will fail on the mutant for some inputs.
        assertTrue(balForwarder == amt);
    }
}

contract Forwarder {
    C target;
    constructor(address _c) { target = C(_c); }
    // Accept ETH and call target.Deposit() so that in target: msg.sender == address(this), tx.origin == original EOA
    function doForward() external payable {
        // call target.Deposit() forwarding the value
        target.Deposit{value: msg.value}();
    }

    receive() external payable {}
}

