// Minimal accepting logger used so Deposit can succeed and let us check the invariant on successful completion.
contract LoggerAccept {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        Message memory m = Message({Sender: _adr, Data: _data, Val: _val, Time: block.timestamp});
        History.push(m);
    }
}

